#!/usr/bin/env bash
# Publish this repo's rules and skills into user-level agent config folders.
# Additive by default: existing non-link files/dirs are left untouched; our own
# links and generated files are refreshed. Safe to re-run anytime (e.g. after
# `git pull`). Pass --clean to wipe the managed folders and republish instead.
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SRC="$REPO_ROOT/.claude"
CLAUDE_DEST="$HOME/.claude"
COPILOT_SKILLS_DEST="$HOME/.copilot/skills"
AGENTS_SKILLS_DEST="$HOME/.agents/skills"
GENERATED_MARKER="Generated by ChekTek/ai scripts/update-config"

# Copilot CLI and VS Code both read ~/.copilot/instructions and ~/.copilot/skills,
# so everything is published once, to the folder both tools already look in.
COPILOT_CLI_INSTRUCTIONS_DEST="${COPILOT_CLI_INSTRUCTIONS_DIR:-$HOME/.copilot/instructions}"

CLEAN=0
ASSUME_YES=0

usage() {
  cat <<'USAGE'
Usage: update-config.sh [--clean] [--yes] [--help]

  --clean  Remove everything from the managed folders before republishing,
           including skills this repo did not create. Use it when the folders
           have drifted and you want to reset to the repo.
  --yes    Skip the --clean confirmation prompt.
  --help   Show this message.

Without --clean the script is additive and never deletes files it did not
generate or link.
USAGE
}

while [ "$#" -gt 0 ]; do
  case "$1" in
    --clean|--fresh) CLEAN=1 ;;
    -y|--yes) ASSUME_YES=1 ;;
    -h|--help) usage; exit 0 ;;
    *)
      echo "unknown option: $1" >&2
      usage >&2
      exit 2
      ;;
  esac
  shift
done

# Folders emptied by --clean, as "directory<TAB>label<TAB>glob".
clean_targets() {
  printf '%s\t%s\t%s\n' \
    "$CLAUDE_DEST/rules" "claude/rules" '*' \
    "$CLAUDE_DEST/skills" "claude/skills" '*' \
    "$COPILOT_SKILLS_DEST" "copilot/skills" '*' \
    "$COPILOT_CLI_INSTRUCTIONS_DEST" "copilot/instructions" '*' \
    "$AGENTS_SKILLS_DEST" "agents/skills" '*'
}

list_clean_entries() {
  clean_targets | while IFS="$(printf '\t')" read -r dir label glob; do
    [ -d "$dir" ] || continue
    for entry in "$dir"/$glob; do
      # A broken symlink fails -e but still needs removing.
      { [ -e "$entry" ] || [ -L "$entry" ]; } || continue
      printf '%s/%s\t%s\n' "$label" "$(basename "$entry")" "$entry"
    done
  done
}

run_clean() {
  entries="$(list_clean_entries)"

  if [ -z "$entries" ]; then
    echo "clean: nothing to remove"
    return 0
  fi

  count="$(printf '%s\n' "$entries" | wc -l | tr -d ' ')"
  echo "clean: permanently removing $count item(s):"
  printf '%s\n' "$entries" | cut -f1 | sed 's/^/  /'

  if [ "$ASSUME_YES" -ne 1 ]; then
    if [ ! -t 0 ]; then
      echo "clean: refusing to run without a terminal; pass --yes to confirm" >&2
      exit 1
    fi
    printf 'Continue? [y/N] '
    read -r reply
    case "$reply" in
      y | Y | yes | YES) ;;
      *)
        echo "clean: aborted"
        exit 1
        ;;
    esac
  fi

  printf '%s\n' "$entries" | while IFS="$(printf '\t')" read -r name entry; do
    rm -rf "$entry"
    echo "removed: $name"
  done

  # Drop ~/.agents entirely when nothing else lives there.
  rmdir "$AGENTS_SKILLS_DEST" "$(dirname "$AGENTS_SKILLS_DEST")" 2>/dev/null || true
}

link_kind() {
  dest="$1"
  label="$2"
  source_kind="$3"
  dest_kind="${4:-$source_kind}"
  mkdir -p "$dest/$dest_kind"
  for item in "$SRC/$source_kind"/*; do
    [ -e "$item" ] || continue # skip if the glob matched nothing
    name="$(basename "$item")"
    target="$dest/$dest_kind/$name"
    if [ -L "$target" ]; then
      ln -sfn "$item" "$target"
      echo "updated: $label/$dest_kind/$name"
    elif [ -e "$target" ]; then
      echo "skip existing: $label/$dest_kind/$name"
    else
      ln -s "$item" "$target"
      echo "linked: $label/$dest_kind/$name"
    fi
  done
}

remove_copilot_artifacts_for_claude_only_skills() {
  for skill_dir in "$SRC/skills-claude-only"/*; do
    [ -d "$skill_dir" ] || continue
    name="$(basename "$skill_dir")"
    skill_target="$COPILOT_SKILLS_DEST/$name"

    if [ -L "$skill_target" ]; then
      link_target="$(readlink "$skill_target")"
      case "$link_target" in
        "$SRC"/*)
          rm "$skill_target"
          echo "removed: copilot/skills/$name"
          ;;
      esac
    fi
  done
}

prune_stale_links() {
  dest="$1"
  label="$2"
  dest_kind="$3"
  dir="$dest/$dest_kind"
  [ -d "$dir" ] || return 0
  for target in "$dir"/*; do
    [ -L "$target" ] || continue
    link="$(readlink "$target")"
    case "$link" in
      "$SRC"/*)
        [ -e "$target" ] && continue
        rm "$target"
        echo "removed stale: $label/$dest_kind/$(basename "$target")"
        ;;
    esac
  done
}

prune_stale_generated_files() {
  dir="$1"
  label="$2"
  [ -d "$dir" ] || return 0
  for target in "$dir"/*.md; do
    [ -f "$target" ] || continue
    grep -q "$GENERATED_MARKER" "$target" || continue
    source_rel="$(sed -n "s|.*$GENERATED_MARKER from \(.*\) -->.*|\1|p" "$target" | head -1)"
    [ -n "$source_rel" ] || continue
    [ -e "$REPO_ROOT/$source_rel" ] && continue
    rm "$target"
    echo "removed stale: $label/$(basename "$target")"
  done
}

can_write_generated_file() {
  target="$1"
  [ ! -e "$target" ] || grep -q "$GENERATED_MARKER" "$target"
}

install_generated_file() {
  content="$1"
  target="$2"
  label="$3"

  if ! can_write_generated_file "$target"; then
    echo "skip existing: $label"
    return
  fi

  mkdir -p "$(dirname "$target")"
  cp "$content" "$target"
  echo "generated: $label"
}

generate_instruction() {
  source="$1"
  relative="${source#$SRC/rules/}"
  name="${relative%.md}"
  name="${name//\//-}"

  tmp="$(mktemp)"
  awk -v name="$name" -v marker="$GENERATED_MARKER from .claude/rules/$relative" '
    NR == 1 && $0 == "---" { in_frontmatter = 1; next }
    in_frontmatter && $0 == "---" {
      print "---"
      for (i = 1; i <= description_count; i++) print descriptions[i]
      printf "name: \"%s\"\n", name
      if (path_count == 1) {
        print "applyTo: " paths[1]
      } else if (path_count > 1) {
        print "applyTo:"
        for (i = 1; i <= path_count; i++) print "    - " paths[i]
      }
      print "---"
      print "<!-- " marker " -->"
      print ""
      in_frontmatter = 0
      next
    }
    in_frontmatter {
      if ($0 ~ /^description:/) {
        descriptions[++description_count] = $0
        in_paths = 0
        next
      }
      if ($0 ~ /^paths:[[:space:]]*$/) {
        in_paths = 1
        next
      }
      if (in_paths && $0 ~ /^[[:space:]]*-[[:space:]]*/) {
        line = $0
        sub(/^[[:space:]]*-[[:space:]]*/, "", line)
        paths[++path_count] = line
        next
      }
      in_paths = 0
      next
    }
    { print }
  ' "$source" > "$tmp"

  install_generated_file "$tmp" "$COPILOT_CLI_INSTRUCTIONS_DEST/$name.instructions.md" \
    "copilot instructions/$name.instructions.md"
  rm -f "$tmp"
}

generate_copilot_instructions() {
  find "$SRC/rules" -type f -name '*.md' -print0 | while IFS= read -r -d '' rule; do
    generate_instruction "$rule"
  done
}

if [ "$CLEAN" -eq 1 ]; then
  run_clean
fi

link_kind "$CLAUDE_DEST" claude rules
link_kind "$CLAUDE_DEST" claude skills
link_kind "$CLAUDE_DEST" claude skills-claude-only skills
link_kind "$(dirname "$COPILOT_SKILLS_DEST")" copilot skills
remove_copilot_artifacts_for_claude_only_skills
prune_stale_links "$CLAUDE_DEST" claude rules
prune_stale_links "$CLAUDE_DEST" claude skills
prune_stale_links "$(dirname "$COPILOT_SKILLS_DEST")" copilot skills
prune_stale_generated_files "$COPILOT_CLI_INSTRUCTIONS_DEST" "copilot instructions"
generate_copilot_instructions
